"use strict";const e=require("./api.js");exports.apiCreateConversation=function(s){return e.post("/conversations",{targetUserId:s})},exports.apiGetConversations=function(){return e.get("/conversations")},exports.apiGetMessages=function(s,t=1,n=20){return e.get(`/conversations/${s}/messages`,{page:t,limit:n})},exports.apiMarkMessagesRead=function(s){return e.put("/messages/read",{conversationId:s})},exports.apiSendMessage=function(s){return e.post("/messages",s)};
